-- monthly_refund_validate(uuid,uuid,jsonb)
CREATE OR REPLACE FUNCTION public.monthly_refund_validate(p_actor uuid, p_order uuid, p_terms jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE o payment_orders;s user_subscriptions;t tickets;g subscription_credit_grants;
 total bigint:=0;paid timestamptz;fee bigint;witness jsonb;card boolean;tax bigint:=0;
 prior payment_orders;old_sub user_subscriptions;upgraded boolean;annual boolean;grant_count integer:=0;
BEGIN
 PERFORM monthly_refund_assert_admin(p_actor);
 PERFORM 1 FROM profiles WHERE id=(SELECT user_id FROM payment_orders WHERE id=p_order) FOR UPDATE;
 SELECT * INTO o FROM payment_orders WHERE id=p_order FOR UPDATE;
 SELECT * INTO s FROM user_subscriptions WHERE id=o.subscription_id FOR UPDATE;
 SELECT * INTO t FROM tickets WHERE id=(p_terms->>'ticketId')::uuid FOR SHARE;
 -- PAY-STRIPE-MP: a card subscription (0222) stores no Stripe ids on its rows; its Stripe subscription is its
 -- 'subscription' reference and its first invoice its 'payment' reference.
 card:=coalesce(o.payment_method IN ('card','card_cn'),false);
 annual:=coalesce(o.billing_cycle='yearly',false);upgraded:=coalesce(o.method_transition='upgrade',false);
 IF upgraded THEN
  SELECT * INTO old_sub FROM user_subscriptions WHERE id=o.method_prior_subscription FOR UPDATE;
  SELECT * INTO prior FROM payment_orders WHERE id=o.source_order_id FOR UPDATE;
  IF NOT card OR old_sub.id IS NULL OR prior.id IS NULL OR prior.subscription_id IS DISTINCT FROM old_sub.id
   OR prior.user_id IS DISTINCT FROM o.user_id OR old_sub.user_id IS DISTINCT FROM o.user_id
   OR prior.item_type IS DISTINCT FROM 'membership_plan' OR prior.purchase_membership_level IS DISTINCT FROM 'pro'
   OR prior.qualification_state IS DISTINCT FROM 'sold' OR prior.method_review_reason IS NOT NULL
   OR old_sub.membership_plan_id IS DISTINCT FROM prior.item_id
   OR old_sub.contract_snapshot IS DISTINCT FROM prior.purchase_snapshot
   OR old_sub.status IS NULL OR old_sub.status NOT IN ('active','canceled','cancelled')
   OR o.purchase_membership_level IS DISTINCT FROM 'gold' OR prior.status IS DISTINCT FROM 'completed'
   OR prior.payment_status IS DISTINCT FROM 'paid' OR prior.fulfilled_at IS NULL
   OR old_sub.credit_release_terminated_at IS NOT NULL OR old_sub.cancel_at_period_end IS DISTINCT FROM 'true'
   OR old_sub.current_period_end IS DISTINCT FROM prior.entitlement_end
   OR p_terms->'priorPro' IS NULL OR jsonb_typeof(p_terms->'priorPro') IS DISTINCT FROM 'object'
   OR (p_terms->'priorPro')-ARRAY['orderId','subscriptionId','providerSubscriptionId','invoiceId','periodEnd','autoRenew']<>'{}'::jsonb
   OR jsonb_typeof(p_terms->'priorPro'->'autoRenew') IS DISTINCT FROM 'boolean'
   OR p_terms->'priorPro'->'autoRenew' IS DISTINCT FROM to_jsonb(prior.auto_renew)
   OR p_terms->'priorPro'->>'orderId' IS DISTINCT FROM prior.id::text
   OR p_terms->'priorPro'->>'subscriptionId' IS DISTINCT FROM old_sub.id::text
   OR (p_terms->'priorPro'->>'periodEnd')::timestamptz IS DISTINCT FROM prior.entitlement_end
   OR prior.payment_channel IS DISTINCT FROM 'stripe' OR old_sub.payment_channel IS DISTINCT FROM 'stripe'
   OR prior.payment_mode IS DISTINCT FROM o.payment_mode OR old_sub.payment_mode IS DISTINCT FROM o.payment_mode
   OR prior.merchant_namespace IS DISTINCT FROM o.merchant_namespace
   OR old_sub.merchant_namespace IS DISTINCT FROM o.merchant_namespace
   OR NOT EXISTS(SELECT 1 FROM payment_provider_refs WHERE order_id=prior.id AND object_type='payment'
    AND external_id=p_terms->'priorPro'->>'invoiceId' AND channel='stripe' AND mode=o.payment_mode
    AND merchant_namespace=o.merchant_namespace)
   OR prior.auto_renew IS NULL OR old_sub.stripe_subscription_id IS NOT NULL
   OR prior.auto_renew AND (prior.payment_method IS NULL OR prior.payment_method NOT IN ('card','card_cn')
    OR jsonb_typeof(p_terms->'priorPro'->'providerSubscriptionId') IS DISTINCT FROM 'string'
    OR NOT EXISTS(SELECT 1 FROM payment_provider_refs WHERE subscription_id=old_sub.id AND object_type='subscription'
     AND external_id=p_terms->'priorPro'->>'providerSubscriptionId' AND channel='stripe' AND mode=o.payment_mode
     AND merchant_namespace=o.merchant_namespace))
   OR prior.auto_renew IS FALSE AND (prior.payment_method IS NULL OR prior.payment_method NOT IN ('wechat_pay','alipay')
    OR p_terms->'priorPro'->'providerSubscriptionId' IS DISTINCT FROM 'null'::jsonb
    OR EXISTS(SELECT 1 FROM payment_provider_refs WHERE subscription_id=old_sub.id AND object_type='subscription'))
   OR pay_dispute_order_frozen(prior.id)
  THEN RAISE EXCEPTION 'PAY_REFUND_PRIOR_PRO_UNRESOLVED'; END IF;
 ELSIF p_terms ? 'priorPro' THEN RAISE EXCEPTION 'PAY_REFUND_PRIOR_PRO_UNRESOLVED'; END IF;
 IF o.id IS NULL OR s.id IS NULL OR t.id IS NULL OR p_terms IS NULL
 OR p_terms->>'kind' IS DISTINCT FROM 'monthly_first_purchase'
 OR p_terms->>'orderId' IS DISTINCT FROM o.id::text OR p_terms->>'userId' IS DISTINCT FROM o.user_id::text
 OR p_terms->>'subscriptionId' IS DISTINCT FROM s.id::text OR s.user_id IS DISTINCT FROM o.user_id
 OR t.user_id IS DISTINCT FROM o.user_id OR t.category IS DISTINCT FROM 'billing' OR t.is_deleted IS DISTINCT FROM 'false'
 OR o.item_type IS DISTINCT FROM 'membership_plan' OR o.billing_cycle IS NULL OR o.billing_cycle NOT IN ('monthly','yearly')
 OR s.billing_cycle IS DISTINCT FROM o.billing_cycle
 OR o.purchase_snapshot->>'billing_cycle' IS DISTINCT FROM o.billing_cycle OR annual AND NOT card
 OR o.source_order_id IS NOT NULL AND NOT upgraded
 OR card AND (o.method_transition IS NOT NULL AND NOT upgraded OR o.offer_kind='founder_renewal')
 OR o.status IS DISTINCT FROM 'completed' OR o.payment_status IS DISTINCT FROM 'paid' OR o.fulfilled_at IS NULL
 OR s.status IS DISTINCT FROM 'active' OR s.credit_release_terminated_at IS NOT NULL
 OR s.current_period_end IS DISTINCT FROM (p_terms->>'periodEnd')::timestamptz OR s.current_period_end<=clock_timestamp()
 OR s.cancel_at_period_end IS DISTINCT FROM p_terms->>'originalCancelAtPeriodEnd'
 OR o.purchase_snapshot IS NULL OR o.purchase_snapshot IS DISTINCT FROM p_terms->'snapshot'
 OR s.contract_snapshot IS DISTINCT FROM o.purchase_snapshot OR s.membership_plan_id IS DISTINCT FROM o.item_id
 OR o.payment_channel IS DISTINCT FROM 'stripe' OR NOT pay_method_mode_allowed(o.payment_channel,o.payment_mode)
 OR s.payment_channel IS DISTINCT FROM 'stripe' OR s.payment_mode IS DISTINCT FROM o.payment_mode
 OR o.merchant_namespace IS NULL OR o.merchant_namespace IS DISTINCT FROM s.merchant_namespace
 OR o.merchant_namespace IS DISTINCT FROM p_terms->>'merchant' OR p_terms->>'mode' IS DISTINCT FROM o.payment_mode
 OR NOT card AND s.stripe_subscription_id IS DISTINCT FROM p_terms->>'providerSubscriptionId'
 OR card AND (s.stripe_subscription_id IS NOT NULL OR o.qualification_state IS DISTINCT FROM 'sold')
 OR p_terms->>'plan' IS NULL OR p_terms->>'plan' NOT IN ('pro','gold')
 OR o.purchase_membership_level IS DISTINCT FROM p_terms->>'plan'
 OR NOT EXISTS(SELECT 1 FROM membership_plans WHERE id=s.membership_plan_id AND level=p_terms->>'plan')
 OR NOT EXISTS(SELECT 1 FROM profiles WHERE id=o.user_id AND status='active' AND is_deleted='false')
 OR o.refund_approval IS NOT NULL AND (o.refund_approval->>'kind' IS DISTINCT FROM 'monthly_first_purchase'
   OR o.refund_approval->>'status' IS DISTINCT FROM 'approved')
 THEN RAISE EXCEPTION 'PAY_MONTHLY_SCOPE_OR_STATE'; END IF;
 paid:=(p_terms->>'paidAt')::timestamptz;
 IF paid IS NULL OR paid>t.created_at OR t.created_at>clock_timestamp()
 OR t.created_at-paid>interval '168 hours' OR t.created_at IS DISTINCT FROM (p_terms->>'submittedAt')::timestamptz
 THEN RAISE EXCEPTION 'PAY_REFUND_WINDOW'; END IF;
 -- An international card (Managed Payments) charged the pre-tax amount plus the tax recorded for this invoice
 -- (0237); the refund adds that tax in full. Other orders carry no tax in their terms.
 IF o.payment_method='card' THEN
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(o.payment_amount_facts,'[]'::jsonb)) f
   WHERE f->>'kind'='tax' AND f->>'evidence_ref'=p_terms->>'invoiceId') THEN RAISE EXCEPTION 'PAY_REFUND_TAX_PENDING'; END IF;
  SELECT coalesce(sum(round((f->>'amount')::numeric*100)),0)::bigint INTO tax FROM jsonb_array_elements(o.payment_amount_facts) f
   WHERE f->>'kind'='tax' AND f->>'evidence_ref'=p_terms->>'invoiceId';
 END IF;
 IF card IS DISTINCT FROM (p_terms ? 'taxMinor') OR card AND (p_terms->>'taxMinor')::bigint IS DISTINCT FROM tax
 THEN RAISE EXCEPTION 'PAY_MONTHLY_CASH'; END IF;
 IF o.amount_total IS NULL OR o.amount_total<=0 OR o.currency IS DISTINCT FROM p_terms->>'currency'
 OR o.amount_total IS DISTINCT FROM (p_terms->>'paidMinor')::bigint
 OR o.amount_total IS DISTINCT FROM (p_terms->>'basisMinor')::bigint
 OR p_terms->>'feePermitted' IS NULL OR p_terms->>'feePermitted' NOT IN ('confirmed','not_permitted')
 OR nullif(btrim(p_terms->>'feeEvidence'),'') IS NULL OR length(p_terms->>'feeEvidence')>160
 OR nullif(p_terms->>'chargeId','') IS NULL OR nullif(p_terms->>'paymentIntentId','') IS NULL
 THEN RAISE EXCEPTION 'PAY_MONTHLY_CASH'; END IF;
 fee:=CASE WHEN p_terms->>'feePermitted'='confirmed' THEN o.amount_total::bigint*6/100 ELSE 0 END;
 IF fee IS DISTINCT FROM (p_terms->>'feeMinor')::bigint
 OR o.amount_total-fee+tax IS DISTINCT FROM (p_terms->>'netMinor')::bigint
 THEN RAISE EXCEPTION 'PAY_MONTHLY_AMOUNT'; END IF;
 IF NOT EXISTS(SELECT 1 FROM payment_provider_refs WHERE order_id=o.id
 AND object_type=CASE WHEN card THEN 'payment' ELSE 'invoice' END
 AND external_id=p_terms->>'invoiceId' AND channel='stripe' AND mode=o.payment_mode AND merchant_namespace=o.merchant_namespace)
 OR NOT EXISTS(SELECT 1 FROM payment_provider_refs WHERE subscription_id=s.id AND object_type='subscription'
 AND external_id=CASE WHEN card THEN p_terms->>'providerSubscriptionId' ELSE s.stripe_subscription_id END
 AND channel='stripe' AND mode=o.payment_mode AND merchant_namespace=o.merchant_namespace)
 OR EXISTS(SELECT 1 FROM payment_provider_refs WHERE order_id=o.id AND object_type='refund')
 -- A card checkout row is created before payment. Only one Stripe confirmed closed unpaid (0204 'released') is left
 -- out of history; an open one may already be paid at Stripe before its webhook lands, so it still counts.
 OR (NOT upgraded AND (SELECT count(*) FROM payment_orders x WHERE x.user_id=o.user_id AND x.item_type='membership_plan'
  AND (NOT card OR x.payment_method IS NULL OR x.payment_method NOT IN ('card','card_cn')
   OR x.qualification_state IS DISTINCT FROM 'released'
   OR x.fulfilled_at IS NOT NULL OR x.payment_status IN ('paid','refunded','partially_refunded')
   OR EXISTS(SELECT 1 FROM payment_provider_refs r WHERE r.order_id=x.id AND r.object_type IN ('payment','invoice'))))<>1)
 OR upgraded AND EXISTS(SELECT 1 FROM payment_orders x WHERE x.user_id=o.user_id AND x.item_type='membership_plan'
  AND x.id<>o.id AND x.subscription_id IS DISTINCT FROM old_sub.id
  AND (x.qualification_state IS DISTINCT FROM 'released' OR x.fulfilled_at IS NOT NULL
   OR x.payment_status IN ('paid','refunded','partially_refunded') OR EXISTS(SELECT 1 FROM payment_provider_refs r
    WHERE r.order_id=x.id AND r.object_type IN ('payment','invoice'))))
 OR (SELECT count(*) FROM user_subscriptions WHERE user_id=o.user_id)<>(CASE WHEN upgraded THEN 2 ELSE 1 END)
 THEN RAISE EXCEPTION 'PAY_MONTHLY_HISTORY'; END IF;
 IF EXISTS(SELECT 1 FROM billing_history h WHERE h.user_id=o.user_id AND h.operation_type='pre_deduct'
 AND NOT EXISTS(SELECT 1 FROM billing_history d WHERE d.user_id=h.user_id
 AND d.operation_type IN ('settle','refund','abort_settle') AND d.metadata->>'preDeductId'=h.id::text))
 THEN RAISE EXCEPTION 'PAY_REFUND_SETTLEMENT_UNRESOLVED'; END IF;
 IF EXISTS(SELECT 1 FROM credit_transactions c WHERE c.user_id=o.user_id AND c.created_at>=paid
 AND (c.counts_as_spend=true AND c.amount<>0 OR c.ledger_type='spend' AND c.amount<>0 OR c.amount<0 AND
 (c.ledger_type IS NULL OR c.ledger_type NOT IN ('refund_clawback','adjustment','expiration','spend')
 OR c.ledger_type='adjustment' AND coalesce(c.source_type,'')<>'admin'
 AND coalesce(c.reason_code,'')<>'bill2_reserve' AND NOT pay_dispute_neutral_adjustment(c.id) -- PAY-D1 withdrawn-refund
 AND coalesce(c.idempotency_key,'') NOT LIKE 'admin_adjustment:%'
 AND coalesce(c.idempotency_key,'') NOT LIKE 'admin_credit_deduction:%')))
 THEN RAISE EXCEPTION 'PAY_REFUND_CONSUMPTION_OR_UNKNOWN'; END IF;
 IF EXISTS(SELECT 1 FROM subscription_credit_grants x WHERE x.user_id=o.user_id
  AND x.source_order_id IS DISTINCT FROM o.id AND (NOT upgraded OR x.subscription_id IS DISTINCT FROM old_sub.id))
 THEN RAISE EXCEPTION 'PAY_REFUND_GRANT_UNRESOLVED'; END IF;
 FOR g IN SELECT * FROM subscription_credit_grants WHERE source_order_id=o.id ORDER BY id FOR UPDATE LOOP
  grant_count:=grant_count+1;
  IF g.source_order_id IS DISTINCT FROM o.id OR g.subscription_id IS DISTINCT FROM s.id
  OR g.status IS DISTINCT FROM 'granted' OR g.accounting_state IS DISTINCT FROM 'trusted' OR g.consumed_amount<>0
  OR g.grant_snapshot IS DISTINCT FROM o.purchase_snapshot OR g.billing_cycle IS DISTINCT FROM o.billing_cycle
  OR g.grant_type IS DISTINCT FROM (CASE WHEN annual THEN 'annual_monthly_release' ELSE 'monthly_invoice' END)
  OR g.stripe_invoice_id IS DISTINCT FROM (CASE WHEN card THEN NULL ELSE p_terms->>'invoiceId' END)
  OR g.stripe_subscription_id IS DISTINCT FROM s.stripe_subscription_id
  OR (NOT annual AND (g.period_start IS DISTINCT FROM s.current_period_start OR g.period_end IS DISTINCT FROM s.current_period_end))
  OR annual AND (g.total_periods IS DISTINCT FROM 12 OR g.period_index IS NULL OR g.period_index NOT BETWEEN 1 AND 12
   OR g.grant_period_key IS DISTINCT FROM 'payment:'||o.id||':'||lpad(g.period_index::text,2,'0')
   OR g.idempotency_key IS DISTINCT FROM g.grant_period_key
   OR g.period_start IS DISTINCT FROM ((o.entitlement_start AT TIME ZONE 'UTC')+make_interval(months=>g.period_index-1)) AT TIME ZONE 'UTC'
   OR g.period_end IS DISTINCT FROM least(o.entitlement_end,((o.entitlement_start AT TIME ZONE 'UTC')
    +make_interval(months=>g.period_index)) AT TIME ZONE 'UTC') OR g.period_start>clock_timestamp()
   OR g.credits_granted IS DISTINCT FROM (o.purchase_snapshot->>'credits')::integer/12
    +(CASE WHEN g.period_index<=(o.purchase_snapshot->>'credits')::integer%12 THEN 1 ELSE 0 END))
  OR g.credits_granted<=0 OR NOT EXISTS(SELECT 1 FROM credit_transactions c WHERE c.id=g.credit_transaction_id
   AND c.user_id=o.user_id AND c.source_order_id=o.id AND c.ledger_type='grant' AND c.amount=g.credits_granted)
  THEN RAISE EXCEPTION 'PAY_REFUND_GRANT_UNRESOLVED'; END IF;
  total:=total+g.credits_granted;
 END LOOP;
 IF total<=0 OR total IS DISTINCT FROM (p_terms->>'credits')::bigint
 OR NOT annual AND total IS DISTINCT FROM (o.purchase_snapshot->>'credits')::bigint+(o.purchase_snapshot->>'bonus_credits')::bigint
 OR annual AND (coalesce((o.purchase_snapshot->>'bonus_credits')::bigint,-1)<>0
  OR grant_count<>(SELECT count(*) FROM generate_series(1,12) idx WHERE
   ((o.entitlement_start AT TIME ZONE 'UTC')+make_interval(months=>idx-1)) AT TIME ZONE 'UTC'<=clock_timestamp())
  OR grant_count<>(SELECT count(DISTINCT period_index) FROM subscription_credit_grants WHERE source_order_id=o.id))
 OR (SELECT credits FROM profiles WHERE id=o.user_id)<total THEN RAISE EXCEPTION 'PAY_REFUND_GRANT_UNRESOLVED'; END IF;
 -- Bind approval to every local financial row, without retaining personal content.
 witness:=jsonb_build_object('order',to_jsonb(o)-ARRAY['refund_approval','updated_at','metadata','checkout_request'],
  'subscription',to_jsonb(s)-ARRAY['metadata','updated_at'],'ticket',jsonb_build_object('id',t.id,'at',t.created_at),
  'ledger',(SELECT jsonb_agg(jsonb_build_array(id,amount,ledger_type,counts_as_spend,source_type,reason_code,
   source_order_id,idempotency_key,created_at) ORDER BY id) FROM credit_transactions WHERE user_id=o.user_id),
  'grants',(SELECT jsonb_agg(to_jsonb(x)-ARRAY['metadata','updated_at'] ORDER BY id) FROM subscription_credit_grants x WHERE user_id=o.user_id),
  'holds',(SELECT jsonb_agg(jsonb_build_array(id,operation_type,metadata->>'preDeductId') ORDER BY id)
   FROM billing_history WHERE user_id=o.user_id));
 IF upgraded THEN witness:=witness||jsonb_build_object('priorPro',
  jsonb_build_object('order',to_jsonb(prior)-ARRAY['metadata','updated_at'],
   'subscription',to_jsonb(old_sub)-ARRAY['metadata','updated_at'])); END IF;
 RETURN md5(witness::text);
END $function$;
